1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type Project = {
11	  id: number;
12	  name: string;
13	  clientId: number;
14	  clientName: string;
15	  archived: boolean;
16	};
17	type Invoice = {
18	  id: number;
19	  projectId: number;
20	  amount: number;
21	  status: string;
22	  issuedDate: string;
23	  dueDate: string;
24	};
25	type Task = { id: number; projectId: number; title: string; done: boolean };
26	type Tag = { id: number; name: string };
27	
28	type LineItem = {
29	  id: number;
30	  invoiceId: number;
31	  description: string;
32	  qty: number;
33	  unitPrice: number;
34	};
35	
36	function money(amount: number): string {
37	  return `$${Number(amount).toFixed(2)}`;
38	}
39	
40	// One charge line while it is being edited on screen: the fields are held as raw strings so the
41	// inputs stay controlled and the total can recompute live as they change.
42	type EditItem = { id: number; description: string; qty: string; unitPrice: string };
43	
44	// An opened invoice's detail: the things it is charging for, listed as line items (description, how
45	// many, price each), the total worked out for you, and a form to add another line. Each line can be
46	// changed in place (save) or removed, and the total re-derives from whatever lines remain. Owns its
47	// own line-item state, scoped to the one invoice it is showing.
48	function InvoiceDetail({
49	  invoiceId,
50	  onChange,
51	  onClose,
52	}: {
53	  invoiceId: number;
54	  onChange: () => void;
55	  onClose: () => void;
56	}) {
57	  const [items, setItems] = useState<EditItem[]>([]);
58	  const [description, setDescription] = useState('');
59	  const [qty, setQty] = useState('');
60	  const [unitPrice, setUnitPrice] = useState('');
61	
62	  async function load() {
63	    const res = await fetch(`/api/invoices/${invoiceId}/line-items`);
64	    const rows: LineItem[] = await res.json();
65	    setItems(
66	      rows.map((li) => ({
67	        id: li.id,
68	        description: li.description,
69	        qty: String(li.qty),
70	        unitPrice: String(li.unitPrice),
71	      })),
72	    );
73	  }
74	
75	  useEffect(() => {
76	    void load();
77	  }, [invoiceId]);
78	
79	  function editField(id: number, field: 'description' | 'qty' | 'unitPrice', value: string) {
80	    setItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
81	  }
82	
83	  function amountOf(li: EditItem): number {
84	    const line = Number(li.qty) * Number(li.unitPrice);
85	    return Number.isFinite(line) ? line : 0;
86	  }
87	
88	  async function save(li: EditItem) {
89	    if (!li.description.trim() || li.qty.trim() === '' || li.unitPrice.trim() === '') {
90	      return;
91	    }
92	    await fetch(`/api/invoices/${invoiceId}/line-items/${li.id}/update`, {
93	      method: 'POST',
94	      headers: { 'Content-Type': 'application/json' },
95	      body: JSON.stringify({
96	        description: li.description,
97	        qty: Number(li.qty),
98	        unitPrice: Number(li.unitPrice),
99	      }),
100	    });
101	    await load();
102	    onChange();
103	  }
104	
105	  async function remove(id: number) {
106	    await fetch(`/api/invoices/${invoiceId}/line-items/${id}/remove`, { method: 'POST' });
107	    await load();
108	    onChange();
109	  }
110	
111	  async function submit(e: React.FormEvent) {
112	    e.preventDefault();
113	    if (!description.trim() || qty.trim() === '' || unitPrice.trim() === '') {
114	      return;
115	    }
116	    await fetch(`/api/invoices/${invoiceId}/line-items`, {
117	      method: 'POST',
118	      headers: { 'Content-Type': 'application/json' },
119	      body: JSON.stringify({
120	        description,
121	        qty: Number(qty),
122	        unitPrice: Number(unitPrice),
123	      }),
124	    });
125	    setDescription('');
126	    setQty('');
127	    setUnitPrice('');
128	    await load();
129	    onChange();
130	  }
131	
132	  const total = items.reduce((sum, li) => sum + amountOf(li), 0);
133	
134	  return (
135	    <section data-testid="invoice-detail">
136	      <button data-testid="invoice-detail-close" type="button" onClick={onClose}>
137	        Back to invoices
138	      </button>
139	
140	      <table data-testid="invoice-lineitems-table">
141	        <tbody>
142	          {items.map((li) => (
143	            <tr key={li.id} data-testid={`lineitem-row-${li.id}`}>
144	              <td>
145	                <input
146	                  data-testid="lineitem-description"
147	                  value={li.description}
148	                  onChange={(e) => editField(li.id, 'description', e.target.value)}
149	                />
150	              </td>
151	              <td>
152	                <input
153	                  data-testid="lineitem-qty"
154	                  value={li.qty}
155	                  onChange={(e) => editField(li.id, 'qty', e.target.value)}
156	                />
157	              </td>
158	              <td>
159	                <input
160	                  data-testid="lineitem-unitprice"
161	                  value={li.unitPrice}
162	                  onChange={(e) => editField(li.id, 'unitPrice', e.target.value)}
163	                />
164	              </td>
165	              <td data-testid="lineitem-amount">{money(amountOf(li))}</td>
166	              <td>
167	                <button
168	                  data-testid={`lineitem-save-${li.id}`}
169	                  type="button"
170	                  onClick={() => save(li)}
171	                >
172	                  Save
173	                </button>
174	                <button
175	                  data-testid={`lineitem-remove-${li.id}`}
176	                  type="button"
177	                  onClick={() => remove(li.id)}
178	                >
179	                  Remove
180	                </button>
181	              </td>
182	            </tr>
183	          ))}
184	        </tbody>
185	      </table>
186	
187	      <p data-testid="invoice-amount">{money(total)}</p>
188	
189	      <form data-testid="lineitem-form" onSubmit={submit}>
190	        <input
191	          data-testid="lineitem-form-description"
192	          placeholder="Description"
193	          value={description}
194	          onChange={(e) => setDescription(e.target.value)}
195	        />
196	        <input
197	          data-testid="lineitem-form-qty"
198	          placeholder="How many"
199	          value={qty}
200	          onChange={(e) => setQty(e.target.value)}
201	        />
202	        <input
203	          data-testid="lineitem-form-unitprice"
204	          placeholder="Price each"
205	          value={unitPrice}
206	          onChange={(e) => setUnitPrice(e.target.value)}
207	        />
208	        <button data-testid="lineitem-form-submit" type="submit">
209	          Add line item
210	        </button>
211	      </form>
212	    </section>
213	  );
214	}
215	
216	// A project's detail: its invoices, what they add up to, and a form to add a new invoice. Owns its
217	// own invoice state, scoped to the one project it is showing.
218	function ProjectDetail({ project }: { project: Project }) {
219	  const [invoices, setInvoices] = useState<Invoice[]>([]);
220	  const [tasks, setTasks] = useState<Task[]>([]);
221	  const [tags, setTags] = useState<Tag[]>([]);
222	  const [allTags, setAllTags] = useState<Tag[]>([]);
223	  const [tagToAdd, setTagToAdd] = useState('');
224	  const [taskFilter, setTaskFilter] = useState<'ALL' | 'OPEN' | 'DONE'>('ALL');
225	  const [amount, setAmount] = useState('');
226	  const [amountError, setAmountError] = useState('');
227	  const [sortByDue, setSortByDue] = useState(false);
228	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
229	
230	  async function load() {
231	    const res = await fetch(`/api/invoices?projectId=${project.id}`);
232	    setInvoices(await res.json());
233	  }
234	
235	  async function loadTasks() {
236	    const res = await fetch(`/api/tasks?projectId=${project.id}`);
237	    setTasks(await res.json());
238	  }
239	
240	  async function loadTags() {
241	    const [mine, all] = await Promise.all([
242	      fetch(`/api/projects/${project.id}/tags`).then((r) => r.json()),
243	      fetch('/api/tags').then((r) => r.json()),
244	    ]);
245	    setTags(mine);
246	    setAllTags(all);
247	  }
248	
249	  useEffect(() => {
250	    void load();
251	    void loadTasks();
252	    void loadTags();
253	  }, [project.id]);
254	
255	  async function toggleTask(id: number) {
256	    await fetch(`/api/tasks/${id}/toggle`, { method: 'POST' });
257	    await loadTasks();
258	  }
259	
260	  async function addTag(e: React.FormEvent) {
261	    e.preventDefault();
262	    if (!tagToAdd) {
263	      return;
264	    }
265	    await fetch(`/api/projects/${project.id}/tags`, {
266	      method: 'POST',
267	      headers: { 'Content-Type': 'application/json' },
268	      body: JSON.stringify({ tagId: Number(tagToAdd) }),
269	    });
270	    setTagToAdd('');
271	    await loadTags();
272	  }
273	
274	  async function removeTag(id: number) {
275	    await fetch(`/api/projects/${project.id}/tags/${id}/remove`, { method: 'POST' });
276	    await loadTags();
277	  }
278	
279	  async function submit(e: React.FormEvent) {
280	    e.preventDefault();
281	    const value = Number(amount);
282	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
283	      setAmountError('Amount must be more than zero');
284	      return;
285	    }
286	    setAmountError('');
287	    await fetch('/api/invoices', {
288	      method: 'POST',
289	      headers: { 'Content-Type': 'application/json' },
290	      body: JSON.stringify({ projectId: project.id, amount: Number(amount) }),
291	    });
292	    setAmount('');
293	    await load();
294	  }
295	
296	  async function send(id: number) {
297	    await fetch(`/api/invoices/${id}/send`, { method: 'POST' });
298	    await load();
299	  }
300	
301	  async function pay(id: number) {
302	    await fetch(`/api/invoices/${id}/pay`, { method: 'POST' });
303	    await load();
304	  }
305	
306	  const shownTasks = tasks.filter((t) =>
307	    taskFilter === 'OPEN' ? !t.done : taskFilter === 'DONE' ? t.done : true,
308	  );
309	
310	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
311	  const shownInvoices = sortByDue
312	    ? [...invoices].sort((a, b) => a.dueDate.localeCompare(b.dueDate))
313	    : invoices;
314	
315	  return (
316	    <section data-testid="project-detail">
317	      <h2 data-testid="project-detail-name">{project.name}</h2>
318	
319	      <div data-testid="project-tags">
320	        {tags.map((tag) => (
321	          <span key={tag.id}>
322	            <span data-testid={`project-tag-${tag.id}`}>{tag.name}</span>
323	            <button
324	              data-testid={`project-tag-remove-${tag.id}`}
325	              type="button"
326	              onClick={() => removeTag(tag.id)}
327	            >
328	              Remove
329	            </button>
330	          </span>
331	        ))}
332	      </div>
333	
334	      <form data-testid="project-tag-form" onSubmit={addTag}>
335	        <select
336	          data-testid="project-tag-add"
337	          value={tagToAdd}
338	          onChange={(e) => setTagToAdd(e.target.value)}
339	        >
340	          <option value="">Add a label</option>
341	          {allTags
342	            .filter((t) => !tags.some((mine) => mine.id === t.id))
343	            .map((t) => (
344	              <option key={t.id} value={String(t.id)}>
345	                {t.name}
346	              </option>
347	            ))}
348	        </select>
349	        <button data-testid="project-tag-add-submit" type="submit">
350	          Add label
351	        </button>
352	      </form>
353	
354	      <select
355	        data-testid="task-filter"
356	        value={taskFilter}
357	        onChange={(e) => setTaskFilter(e.target.value as 'ALL' | 'OPEN' | 'DONE')}
358	      >
359	        <option value="ALL">All tasks</option>
360	        <option value="OPEN">Open</option>
361	        <option value="DONE">Done</option>
362	      </select>
363	
364	      <table data-testid="project-tasks-table">
365	        <tbody>
366	          {shownTasks.map((t) => (
367	            <tr key={t.id} data-testid={`task-row-${t.id}`}>
368	              <td data-testid="task-title">{t.title}</td>
369	              <td data-testid="task-status">{t.done ? 'DONE' : 'OPEN'}</td>
370	              <td>
371	                <button data-testid={`task-toggle-${t.id}`} onClick={() => toggleTask(t.id)}>
372	                  {t.done ? 'Reopen' : 'Tick off'}
373	                </button>
374	              </td>
375	            </tr>
376	          ))}
377	        </tbody>
378	      </table>
379	
380	      <form data-testid="invoice-form" onSubmit={submit}>
381	        <input
382	          data-testid="invoice-form-amount"
383	          placeholder="Amount"
384	          value={amount}
385	          onChange={(e) => setAmount(e.target.value)}
386	        />
387	        <button data-testid="invoice-form-submit" type="submit">
388	          Add invoice
389	        </button>
390	        {amountError && (
391	          <p data-testid="invoice-form-amount-error" role="alert">
392	            {amountError}
393	          </p>
394	        )}
395	      </form>
396	
397	      <button data-testid="invoice-sort-due" type="button" onClick={() => setSortByDue(true)}>
398	        Sort by due date
399	      </button>
400	
401	      {openInvoiceId === null ? (
402	        <>
403	          <table data-testid="project-invoices-table">
404	            <tbody>
405	              {shownInvoices.map((inv) => (
406	                <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
407	                  <td data-testid="invoice-amount">{money(inv.amount)}</td>
408	                  <td data-testid="invoice-issued">{inv.issuedDate}</td>
409	                  <td data-testid="invoice-due">{inv.dueDate}</td>
410	                  <td data-testid="invoice-status">{inv.status}</td>
411	                  <td>
412	                    <button
413	                      data-testid={`invoice-open-${inv.id}`}
414	                      onClick={() => setOpenInvoiceId(inv.id)}
415	                    >
416	                      Open
417	                    </button>
418	                    {inv.status === 'DRAFT' && (
419	                      <button data-testid={`invoice-send-${inv.id}`} onClick={() => send(inv.id)}>
420	                        Send
421	                      </button>
422	                    )}
423	                    {inv.status === 'SENT' && (
424	                      <button data-testid={`invoice-pay-${inv.id}`} onClick={() => pay(inv.id)}>
425	                        Mark paid
426	                      </button>
427	                    )}
428	                  </td>
429	                </tr>
430	              ))}
431	            </tbody>
432	          </table>
433	
434	          <p data-testid="project-invoices-total">{money(total)}</p>
435	        </>
436	      ) : (
437	        <InvoiceDetail
438	          invoiceId={openInvoiceId}
439	          onChange={load}
440	          onClose={() => setOpenInvoiceId(null)}
441	        />
442	      )}
443	    </section>
444	  );
445	}
