447	function ProjectsPage() {
448	  const [projects, setProjects] = useState<Project[]>([]);
449	  const [clients, setClients] = useState<Client[]>([]);
450	  const [name, setName] = useState('');
451	  const [clientId, setClientId] = useState('');
452	  const [openId, setOpenId] = useState<number | null>(null);
453	  // Archived projects are tucked away (retained, not deleted) and hidden by default; this toggle
454	  // reveals them again.
455	  const [showArchived, setShowArchived] = useState(false);
456	
457	  async function loadProjects() {
458	    const res = await fetch('/api/projects');
459	    setProjects(await res.json());
460	  }
461	
462	  async function loadClients() {
463	    const res = await fetch('/api/clients');
464	    setClients(await res.json());
465	  }
466	
467	  useEffect(() => {
468	    void loadProjects();
